	}
	// testKeyspaceLock(t, ts)

	if err := ts.CreateKeyspace(ctx, "test_keyspace", &topodatapb.Keyspace{}); err != nil {
		fmt.Println(fmt.Sprintf("CreateKeyspace: %v", err))
	}

	if err := ts.CreateShard(ctx, "test_keyspace", "0"); err != nil {
